cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <vector>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void conv_transpose3d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ Bias,
    T* __restrict__ Y,
    int N, int Cin, int D, int H, int Win,
    int Cout, int Dout, int Hout, int Wout,
    int kD, int kH, int kW,
    int strideD, int strideH, int strideW,
    int padD, int padH, int padW,
    int groups, int Cin_g, int Cout_g,
    int num_co_tiles)
{
  constexpr int Threads   = 128;
  constexpr int CoTile    = 16;
  constexpr int CinChunk  = 32;

  const int tid = threadIdx.x;
  const int n   = blockIdx.z;
  const int gy  = blockIdx.y;
  const int g       = gy / num_co_tiles;
  const int co_tile = gy % num_co_tiles;
  const int co_base = co_tile * CoTile;

  const int P_total = Dout * Hout * Wout;
  const int p = blockIdx.x * Threads + tid;

  bool p_valid = p < P_total;
  int od = 0, oh = 0, ow = 0;
  if (p_valid) {
    od = p / (Hout * Wout);
    int rem = p - od * Hout * Wout;
    oh = rem / Wout;
    ow = rem - oh * Wout;
  }

  int64_t sXn = (int64_t)Cin * D * H * Win;
  int64_t sXc = (int64_t)D * H * Win;
  int64_t sXd = (int64_t)H * Win;
  int64_t sXh = (int64_t)Win;

  int64_t sYn = (int64_t)Cout * Dout * Hout * Wout;
  int64_t sYc = (int64_t)Dout * Hout * Wout;
  int64_t sYd = (int64_t)Hout * Wout;
  int64_t sYh = (int64_t)Wout;

  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, D, H, Win),
      make_stride(sXc, sXd, sXh, Int<1>{}));

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Dout, Hout, Wout),
      make_stride(sYc, sYd, sYh, Int<1>{}));

  int64_t sWci = (int64_t)Cout_g * kD * kH * kW;
  int64_t sWco = (int64_t)kD * kH * kW;
  int64_t sWkd = (int64_t)kH * kW;
  int64_t sWkh = (int64_t)kW;

  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cin, Cout_g, kD, kH, kW),
      make_stride(sWci, sWco, sWkd, sWkh, Int<1>{}));

  __shared__ T sW_raw[CinChunk * CoTile];
  auto sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<CinChunk>{}, Int<CoTile>{}),
      make_stride(Int<CoTile>{}, Int<1>{}));

  float acc[CoTile];
  #pragma unroll
  for (int cc = 0; cc < CoTile; ++cc) {
    int co_actual = co_base + cc;
    float bval = 0.0f;
    if (Bias != nullptr && co_actual < Cout_g) {
      bval = (float)Bias[g * Cout_g + co_actual];
    }
    acc[cc] = bval;
  }

  for (int kd = 0; kd < kD; ++kd) {
    int numD = od + padD - kd;
    bool dvalid = p_valid && (numD >= 0) && (numD % strideD == 0);
    int id = dvalid ? (numD / strideD) : -1;
    dvalid = dvalid && (id < D);

    for (int kh = 0; kh < kH; ++kh) {
      int numH = oh + padH - kh;
      bool hvalid = dvalid && (numH >= 0) && (numH % strideH == 0);
      int ih = hvalid ? (numH / strideH) : -1;
      hvalid = hvalid && (ih < H);

      for (int kw = 0; kw < kW; ++kw) {
        int numW = ow + padW - kw;
        bool wvalid = hvalid && (numW >= 0) && (numW % strideW == 0);
        int iw = wvalid ? (numW / strideW) : -1;
        wvalid = wvalid && (iw < Win);

        for (int cin_base = 0; cin_base < Cin_g; cin_base += CinChunk) {
          int chunk_size = min(CinChunk, Cin_g - cin_base);

          for (int idx = tid; idx < CinChunk * CoTile; idx += Threads) {
            int cin_local = idx / CoTile;
            int co_local  = idx % CoTile;
            T wval = T(0);
            if (cin_local < chunk_size) {
              int cin_global = g * Cin_g + cin_base + cin_local;
              int co_actual  = co_base + co_local;
              if (co_actual < Cout_g) {
                wval = mW(cin_global, co_actual, kd, kh, kw);
              }
            }
            sW(cin_local, co_local) = wval;
          }
          __syncthreads();

          if (wvalid) {
            #pragma unroll 4
            for (int cin_local = 0; cin_local < chunk_size; ++cin_local) {
              int cin_global = g * Cin_g + cin_base + cin_local;
              float xval = (float)mX(cin_global, id, ih, iw);
              #pragma unroll
              for (int cc = 0; cc < CoTile; ++cc) {
                acc[cc] += xval * (float)sW(cin_local, cc);
              }
            }
          }
          __syncthreads();
        }
      }
    }
  }

  if (p_valid) {
    #pragma unroll
    for (int cc = 0; cc < CoTile; ++cc) {
      int co_actual = co_base + cc;
      if (co_actual < Cout_g) {
        mY(g * Cout_g + co_actual, od, oh, ow) = static_cast<T>(acc[cc]);
      }
    }
  }
}

torch::Tensor conv_transpose3d_forward(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    std::vector<int64_t> stride,
    std::vector<int64_t> padding,
    std::vector<int64_t> output_padding,
    int64_t groups)
{
  TORCH_CHECK(x.is_cuda() && weight.is_cuda(), "x and weight must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kFloat && weight.scalar_type() == at::kFloat,
              "only float32 supported");
  TORCH_CHECK(x.dim() == 5, "x must be [N,C,D,H,W]");
  TORCH_CHECK(weight.dim() == 5, "weight must be [Cin, Cout/groups, kD,kH,kW]");
  TORCH_CHECK(stride.size() == 3 && padding.size() == 3 && output_padding.size() == 3,
              "stride/padding/output_padding must have 3 elements");

  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();

  int64_t N   = x_c.size(0);
  int64_t Cin = x_c.size(1);
  int64_t D   = x_c.size(2);
  int64_t H   = x_c.size(3);
  int64_t Win = x_c.size(4);

  int64_t Cout_g = w_c.size(1);
  int64_t kD = w_c.size(2);
  int64_t kH = w_c.size(3);
  int64_t kW = w_c.size(4);
  TORCH_CHECK(w_c.size(0) == Cin, "weight.size(0) must equal Cin");

  int64_t Cin_g = Cin / groups;
  int64_t Cout  = Cout_g * groups;

  int64_t strideD = stride[0], strideH = stride[1], strideW = stride[2];
  int64_t padD = padding[0], padH = padding[1], padW = padding[2];
  int64_t opD = output_padding[0], opH = output_padding[1], opW = output_padding[2];

  int64_t Dout = (D - 1) * strideD - 2 * padD + (kD - 1) + opD + 1;
  int64_t Hout = (H - 1) * strideH - 2 * padH + (kH - 1) + opH + 1;
  int64_t Wout = (Win - 1) * strideW - 2 * padW + (kW - 1) + opW + 1;

  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "Invalid output size computed");

  auto y = torch::zeros({N, Cout, Dout, Hout, Wout}, x.options());

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (bias.has_value()) {
    b_c = bias.value().contiguous();
    TORCH_CHECK(b_c.numel() == Cout, "bias size mismatch");
    b_ptr = b_c.data_ptr<float>();
  }

  constexpr int Threads = 128;
  constexpr int CoTile  = 16;
  int64_t P_total = Dout * Hout * Wout;
  int64_t num_co_tiles = (Cout_g + CoTile - 1) / CoTile;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + Threads - 1) / Threads),
      (unsigned)(groups * num_co_tiles),
      (unsigned)N
  );

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv_transpose3d_kernel<float><<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(), w_c.data_ptr<float>(), b_ptr, y.data_ptr<float>(),
      (int)N, (int)Cin, (int)D, (int)H, (int)Win,
      (int)Cout, (int)Dout, (int)Hout, (int)Wout,
      (int)kD, (int)kH, (int)kW,
      (int)strideD, (int)strideH, (int)strideW,
      (int)padD, (int)padH, (int)padW,
      (int)groups, (int)Cin_g, (int)Cout_g,
      (int)num_co_tiles
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv_transpose3d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv_transpose3d_ext = load_inline(
    name="cute_conv_transpose3d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv_transpose3d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Transposed 3D convolution implemented with a custom CUDA kernel using CuTe.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0),
                 output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = tuple(kernel_size)
        self.stride = tuple(stride)
        self.padding = tuple(padding)
        self.output_padding = tuple(output_padding)
        self.groups = int(groups)

        kD, kH, kW = self.kernel_size
        self.weight = nn.Parameter(
            torch.empty(self.in_channels, self.out_channels // self.groups, kD, kH, kW)
        )
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()
        self._ext = conv_transpose3d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv_transpose3d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            list(self.stride),
            list(self.padding),
            list(self.output_padding),
            int(self.groups),
        )

